function getScenesForCampaign(campaign) {
	return campaign === "students-parents" ? STUDENT_PARENT_SCENES : SCHOOL_SCENES;
}
function getDefaultCustomStarts(campaign) {
	const map = {};
	for (const scene of getScenesForCampaign(campaign)) map[scene.id] = scene.defaultSongStartSec;
	return map;
}
